import sys
import re
import openpyxl


def group_number(group_name):
    m = re.search(r"(\d+)", group_name)
    return int(m.group(1)) if m else 0


def main():
    input_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(input_path, data_only=False)
    ws = wb.active

    # Build lookup dict {code: group} from columns G/H of the active sheet.
    lookup = {}
    for row in ws.iter_rows():
        g = row[6].value  # column G (index 6)
        h = row[7].value  # column H (index 7)
        if g is not None and h is not None:
            code = str(g).strip()
            group = str(h).strip()
            code = code.split(";")[0].strip()  # handle any trailing ';'
            if code and group and not code.lower().startswith("lookup"):
                lookup[code] = group

    # Fill column D (index 3) for rows 5..10.
    for r in range(5, 11):
        cell_c = ws.cell(row=r, column=3).value
        if cell_c is None:
            continue
        codes = [c.strip() for c in str(cell_c).split(";")]
        codes = [c for c in codes if c]
        groups = []
        for code in codes:
            grp = lookup.get(code)
            if grp and grp not in groups:
                groups.append(grp)
        groups.sort(key=group_number)
        if not groups:
            result = ""
        elif len(groups) == 1:
            result = groups[0]
        else:
            result = ", ".join(groups)
        ws.cell(row=r, column=4).value = result

    wb.save(output_path)


if __name__ == "__main__":
    main()

