#!/usr/bin/env python3
import sys
import openpyxl

def is_trigger(val):
    """Return True if val is blank or equals one of the delete values."""
    if val is None:
        return True
    if isinstance(val, str):
        return val.strip() in ("-", "0", "$", "$0", "$0.0")
    if isinstance(val, (int, float)):
        return val == 0
    return False

def main():
    src, dst = sys.argv[1], sys.argv[2]
    wb = openpyxl.load_workbook(src)
    ws = wb["Sheet2"]

    # The sheet spans A1:K54. Row 1 is the header; data rows are 2..max_row.
    # Delete an entire row when BOTH column J (10) and column K (11) satisfy the
    # trigger condition (blank or one of -, 0, $, $0, $0.0).
    max_row = ws.max_row
    rows_to_delete = []
    for r in range(2, max_row + 1):
        j = ws.cell(r, 10).value
        k = ws.cell(r, 11).value
        if is_trigger(j) and is_trigger(k):
            rows_to_delete.append(r)

    # Delete from the bottom up so row indices stay valid.
    for r in sorted(rows_to_delete, reverse=True):
        ws.delete_rows(r, 1)

    wb.save(dst)
    print("Deleted rows:", rows_to_delete)

if __name__ == "__main__":
    main()

