def build_formula(row):
    """Return an Excel formula string for cell H<row>."""
    if row > 5:
        # LOOKUP finds the row of the last cell above `row` whose value is not
        # 5551234 (the incoming call that started the current group). The count
        # of transfers is then row - that_incoming_row.
        lookup = ("LOOKUP(2,1/(D$5:D" + str(row - 1)
                  + "<>5551234),ROW(D$5:D" + str(row - 1) + "))")
    else:
        # First data row is always the incoming call; no transfers before it.
        lookup = "ROW()"
    return ("=IF(AND(D" + str(row) + "=5551234,D" + str(row + 1)
            + "<>5551234),ROW()-" + lookup + ',"")')

