output_path = sys.argv[2]

wb = openpyxl.load_workbook(input_path)
extract = wb["Extract"]
desired = wb["Desired Result"]

# Read headers from Desired Result row 1 (columns 2..9)
headers = [desired.cell(row=1, column=c).value for c in range(2, desired.max_column + 1)]

# Read the Extract data
data = {}
persons_order = []
for row in extract.iter_rows(min_row=2, values_only=True):
    person, car, value = row[0], row[1], row[2]
    if person is None:
        continue
    if person not in data:
        data[person] = {}
        persons_order.append(person)
    data[person][car] = value

# Determine client order as they appear in Desired Result column A (rows 2..5)
client_rows = []
for r in range(2, desired.max_row + 1):
    name = desired.cell(row=r, column=1).value
    if name is not None:
        client_rows.append((name, r))

# Fill cells B2:I5
for name, r in client_rows:
    client_data = data.get(name, {})
    for ci in range(len(headers)):
        header = headers[ci]
        c = ci + 2
        val = client_data.get(header)
        if val is None:
            desired.cell(row=r, column=c).value = ""
        else:
            desired.cell(row=r, column=c).value = val

wb.save(output_path)
print("saved", output_path)

